export interface Tool { name: string; url: string; description: string; tags: ('free' | 'paid' | 'cli')[]; }
export interface ToolCategory { category: string; items: Tool[]; }

export function getDomain(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url;
  }
}

export function normalizeToolkit(raw: ToolCategory[]): ToolCategory[] {
  return raw.map(section => ({
    ...section,
    items: section.items.map(tool => ({
      ...tool,
      description: tool.description || 'Outil ' + tool.name,
    }))
  }));
}

